func guRect(pa *port.Cells, page int32, flags int32, fill int32, x0 int32, y0 int32, x1 int32, y1 int32) int32 {
	// A painted box with no geometry kept (read by its box).
	var r int32 = evidence.PaNew(pa, page, evidence.PaRect(), x0, y0, x1, y1)
	evidence.PaSet(pa, r, evidence.PfFlags(), flags)
	evidence.PaSet(pa, r, evidence.PfFill(), fill)
	return r
}

func TestTheRowsOfAVectorOnlyPage(emonT *testing.T) {
	var pa *port.Cells = port.NewCells()
	var pts *port.Cells = port.NewCells()
	var mk *port.Cells = port.NewCells()
	var im *port.Cells = port.NewCells()
	var grl *port.Cells = port.NewCells()
	var gfl *port.Cells = port.NewCells()
	var cand *port.Cells = port.NewCells()
	var refs *port.Cells = port.NewCells()
	var ggp *port.Cells = port.NewCells()
	var grg *port.Cells = port.NewCells()
	var h int32 = guRect(pa, 1, evidence.PgFilled(), 0, 1000, 4950, 21000, 5050)
	var v int32 = guRect(pa, 1, evidence.PgFilled(), 0, 1000, 5000, 1100, 9000)
	var b int32 = guRect(pa, 1, evidence.PgFilled(), 0, 1000, 6950, 21000, 7050)
	var x int32 = guRect(pa, 1, evidence.PgFilled(), 0, 1000, 8950, 21000, 9050)
	var f int32 = guRect(pa, 1, evidence.PgFilled(), 14540253, 2000, 12000, 12000, 15000)
	var p int32 = guRect(pa, 1, evidence.PgFilled()+evidence.PgPattern(), -1, 3000, 12000, 8000, 15000)
	var q int32 = guRect(pa, 2, evidence.PgFilled(), 0, 1000, 9950, 21000, 10050)
	port.AssertThat(emonT, (v+(f+(p+q))) > 0, "the other paths are painted")
	evidence.PaSet(pa, b, evidence.PfVchk(), evidence.VcBlend())
	evidence.PaSet(pa, x, evidence.PfVis(), 3)
	evidence.PaSet(pa, h, evidence.PfZ(), 4)
	port.AssertEq(emonT, gfuse.GfDoc(pa, pts, mk, im, 2, gvec.GvSegments(), grl, gfl, cand), 4, "four rules: the hidden one is nothing")
	port.AssertEq(emonT, glayer.GflCount(gfl), 2, "two fills")
	port.AssertEq(emonT, glayer.GlCheck(grl, gfl, ggp, grg, refs), 0, "sound")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 0), 1, "the first rule's page")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 5), 1000, "its centre line starts at its left end")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 6), 5000, "on its centre")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 9), 100, "one point thick")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 10), glayer.GoH(), "horizontal")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 11), 0, "at angle 0")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 12), 0, "black")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 14), 1, "from the vector source")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 15), 1, "which is the winner")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 16), 501, "by rule 501")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 17), 900, "at 900")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 19), -1, "no group before P7.G")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 20), 4, "its path's z")
	port.AssertEq(emonT, glayer.GrlGet(grl, 1, 10), glayer.GoV(), "the second is vertical")
	port.AssertEq(emonT, glayer.GrlGet(grl, 1, 11), 9000, "at 9000")
	port.AssertEq(emonT, glayer.GrlGet(grl, 1, 5), 1050, "on its centre")
	port.AssertEq(emonT, glayer.GrlGet(grl, 2, 16), 514, "blended paint is not exactly known")
	port.AssertEq(emonT, glayer.GrlGet(grl, 2, 17), 700, "700")
	port.AssertEq(emonT, glayer.GrlGet(grl, 3, 0), 2, "the fourth is on page 2")
	port.AssertEq(emonT, glayer.GflGet(gfl, 0, 9), 560, "a fill by 560")
	port.AssertEq(emonT, glayer.GflGet(gfl, 0, 10), 900, "at 900")
	port.AssertEq(emonT, glayer.GflGet(gfl, 0, 5), 14540253, "its colour")
	port.AssertEq(emonT, glayer.GflGet(gfl, 0, 6), 866, "its lightness")
	port.AssertEq(emonT, glayer.GflGet(gfl, 1, 9), 562, "a pattern fill by 562")
	port.AssertEq(emonT, glayer.GflGet(gfl, 1, 10), 600, "at 600")
	port.AssertEq(emonT, glayer.GflGet(gfl, 1, 5), -1, "of no colour")
	port.AssertEq(emonT, glayer.GflGet(gfl, 1, 11), glayer.GqfPattern(), "flagged pattern")
}

func TestASlantedLineIsASlantAndTheModesAgreeOnPlainBoxes(emonT *testing.T) {
	var pa *port.Cells = port.NewCells()
	var pts *port.Cells = port.NewCells()
	var mk *port.Cells = port.NewCells()
	var im *port.Cells = port.NewCells()
	var grl *port.Cells = port.NewCells()
	var gfl *port.Cells = port.NewCells()
	var cand *port.Cells = port.NewCells()
	var r int32 = evidence.PaNew(pa, 1, evidence.PaOther(), 0, 0, 10000, 10000)
	evidence.PaSet(pa, r, evidence.PfFlags(), evidence.PgStroked())
	evidence.PaSet(pa, r, evidence.PfStroke(), 0)
	evidence.PaSet(pa, r, evidence.PfWidth(), 50)
	evidence.PaSet(pa, r, evidence.PfPfirst(), 0)
	evidence.PaSet(pa, r, evidence.PfPcount(), 2)
	evidence.PtAdd(pts, 0, 0, evidence.PoMove())
	evidence.PtAdd(pts, 10000, 10000, evidence.PoLine())
	port.AssertEq(emonT, gfuse.GfDoc(pa, pts, mk, im, 1, gvec.GvSegments(), grl, gfl, cand), 1, "one rule")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 10), glayer.GoSlant(), "slanted")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 11), 13500, "at 135 degrees (page space has y down)")
	// a plain thin box: the two modes give the same row
	port.CellsDrop(pa, 0)
	guRect(pa, 1, evidence.PgFilled(), 0, 1000, 4950, 21000, 5050)
	port.AssertEq(emonT, gfuse.GfDoc(pa, pts, mk, im, 1, gvec.GvLegacy(), grl, gfl, cand), 1, "legacy: one rule")
	var a int32 = glayer.GrlGet(grl, 0, 5)
	var b int32 = glayer.GrlGet(grl, 0, 7)
	var c int32 = glayer.GrlGet(grl, 0, 6)
	port.AssertEq(emonT, gfuse.GfDoc(pa, pts, mk, im, 1, gvec.GvSegments(), grl, gfl, cand), 1, "segments: one rule")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 5), a, "the same left end")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 7), b, "the same right end")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 6), c, "the same centre")
}
